import {RECIPE,SLOTS,STATIONS} from './simulation.js';
const steps={
 grindPlace:['Prepare espresso','Slide the coffee basket under the grinder.','portafilter','basket'],
 grind:['Grind','Hold the grinder lever until the basket is full.','grindLever','basket'],
 tamp:['Tamp','Drag the wooden-handled tamper onto the coffee grounds, then let go to press.','tamper','basket'],
 lock:['Lock','Slide the filled basket into the round brew head.','portafilter','brew'],
 cup:['Place cup','Place the little cup under the coffee spouts.','cup','brew'],
 brew:['Brew','Tap the brew lever to make your espresso.','brewLever','brew'],
 extracting:['Brewing','Your espresso is brewing…','brewLever','brew'],
 cupFull:['Pour espresso','Bring the cup over the glass and let go to pour.','cup','glassPour'],
 ice:['Add ice','Bring a scoop of ice over your glass.','iceScoop','glass'],
 milk:['Add milk','Bring the milk jug over the glass and let go to pour.','milk','glass'],
 espresso:['Add espresso','Bring your espresso over the glass and let go to pour.','cup','glassPour'],
 extraEspresso:['Add espresso','Bring your espresso over the glass and let go to pour.','cup','glassPour'],
 glassFull:['Glass full','Set your coffee on the coaster when you’re ready.','glass','hero'],
 sugar:['Add sugar','Want it sweeter? Dip the spoon in the sugar, then bring it over your glass.','spoon','glass'],
 stir:['Stir','Add another spoonful of sugar, or put the empty spoon in your glass to stir.','spoon','glass'],
 done:['Ready','Set your coffee on the coaster when you’re ready.','glass','hero'],
 served:['Ready','Your iced coffee is ready.','glass','served']
};
export function stepFor(s){if(s.served)return'served';if(s.objects.spoon.slot==='stir')return'stir';const v=s.vessels.glass.contents,preparing=s.completedShots===0||s.grounds>0||s.shotProgress>0||s.brewing||['grinder','group'].includes(s.objects.portafilter.slot)||(v.coffee<1&&s.vessels.cup.contents.coffee<1&&s.ice.every(c=>!c.inside));if(preparing){if(s.grounds<RECIPE.grounds-.01)return s.objects.portafilter.slot==='grinder'?'grind':'grindPlace';if(s.compression<.65)return'tamp';if(s.objects.portafilter.slot!=='group'||s.lock<.9)return'lock';if(s.objects.cup.slot!=='brew')return'cup';if(s.brewProblem()==='cupFull')return'cupFull';return s.brewing?'extracting':'brew';}if(s.ice.filter(c=>c.inside).length<4)return'ice';if(occupiedGlassFull(s))return v.coffee>0&&v.milk>0&&s.mixing<.995?'stir':'glassFull';if(v.milk<149.99)return'milk';if(s.vessels.cup.contents.coffee>0.01)return occupiedGlassFull(s)?'glassFull':v.coffee<35.99?'espresso':'extraEspresso';if(v.coffee<35.99)return'grindPlace';if(occupiedGlassFull(s))return'glassFull';if(!s.sugarSkipped&&v.sugar<5)return'sugar';return s.mixing<.995?'stir':'done';}
const occupiedGlassFull=s=>s.vessels.glass.capacity-(s.vessels.glass.contents.coffee+s.vessels.glass.contents.milk+s.vessels.glass.contents.ice+s.vessels.glass.contents.sugar*.65)<.01;
export function guide(s){const key=stepFor(s),[title,text,object,pose]=steps[key];let detail='';if(key==='grind')detail=`${s.grounds.toFixed(0)} / 18 g`;if(key==='extracting'||key==='brew')detail=`${s.shotProgress.toFixed(0)} / 36 ml`;if(key==='ice')detail=`${s.ice.filter(c=>c.inside).length} / ${RECIPE.ice} cubes`;if(key==='milk')detail=`${s.vessels.glass.contents.milk.toFixed(0)} / 150 ml`;if(key==='espresso'||key==='extraEspresso')detail=`${s.vessels.glass.contents.coffee.toFixed(0)} ml espresso`;if(key==='sugar'||key==='stir')detail=`${s.vessels.glass.contents.sugar.toFixed(1).replace(/\.0$/,'')} g sugar`;if(key==='stir'&&s.objects.spoon.slot==='stir')detail=`${Math.round(s.mixing*100)}% mixed`;if(key==='served')detail='Ready';if(key==='done')detail=`${s.completedShots} shot${s.completedShots===1?'':'s'}`;return{key,title,text:s.pouring?`Pouring ${s.pouring.from==='milk'?'milk':'espresso'}…`:key==='stir'&&s.objects.spoon.slot==='stir'?(occupiedGlassFull(s)?'Drag left and right to stir your coffee.':'Drag left and right to stir. Pull the spoon down to take it out.'):key==='stir'&&occupiedGlassFull(s)?'Your glass is full. Put the spoon in and stir.':s.spoonLoaded&&['sugar','stir','done'].includes(key)?'Bring the spoon over your glass to add the sugar.':text,object,pose,detail};}
export function recovery(s){const p=s.brewProblem();return{power:'Turn on the power switch first.',grind:'Fill the basket: hold the grinder lever until it reaches 18 g.',tamp:'First, drag the wooden-handled tamper onto the grounds and let go to press.',lock:'Drag the portafilter into the group head to lock it.',cup:'Place the small cup beneath the spouts.',cupFull:'Pour the espresso already in the small cup before brewing another shot.'}[p]??'';}
export function cuePath(s,g){const pos=id=>s.objects[id].position,mouth=[...pos('glass')];mouth[1]+=1.45;
 if(g.key==='grindPlace')return[pos('portafilter'),SLOTS.grinder];if(g.key==='grind')return[[-1.96,1.95,.72],[-1.96,1.68,.72]];if(g.key==='tamp')return[pos('tamper'),pos('portafilter')];if(g.key==='lock')return[pos('portafilter'),SLOTS.group];if(g.key==='cup')return[pos('cup'),SLOTS.brew];if(['brew','extracting'].includes(g.key))return[[.37,2.46,.68],[.37,2.18,.82]];if(g.key==='ice')return[pos('iceScoop'),mouth];if(g.key==='sugar')return[pos('spoon'),s.spoonLoaded?mouth:[STATIONS.sugar[0],.28,STATIONS.sugar[2]]];if(g.key==='stir')return s.objects.spoon.slot==='stir'?[[mouth[0]-.35,mouth[1]-.35,mouth[2]],[mouth[0]+.35,mouth[1]-.35,mouth[2]]]:[pos('spoon'),mouth];if(g.key==='milk'||g.key==='espresso'||g.key==='extraEspresso'||g.key==='cupFull')return[pos(g.object),mouth];return[mouth,mouth];}
export class GuidanceClock{constructor(){this.reset();}reset(){this.signature='';this.idle=0;this.cue=0;}update(s,dt,active){this.cue=Math.max(0,this.cue-dt);const g=guide(s),signature=g.key+g.detail+s.compression+s.lock+s.spoonLoaded;if(signature!==this.signature){this.signature=signature;this.idle=0;this.cue=g.key==='tamp'?4.5:0;}else if(!active&&g.key!=='done'&&g.key!=='served'&&g.key!=='extracting')this.idle+=dt;if(this.idle>=8){this.cue=3;this.idle=0;}return g;}show(){this.cue=3;this.idle=0;}}
